param([switch]$Apply); Write-Host '=== GOVERNOR GLOBAL SCAN ACTIVE ===' -ForegroundColor Cyan; $manifest = Get-Content -Raw -Path 'C:\Users\Hubert111\Documents\Radiworks\governors\governor_manifest.json' | ConvertFrom-Json; $projects = $manifest.governed_projects; foreach ($projName in $projects.psobject.properties.Name) { $projPath = $projects.$projName; Write-Host 'Scanning Memory for:' $projName -ForegroundColor Yellow; $memPath = Join-Path $projPath 'project_memories'; if (Test-Path $memPath) { Write-Host '  -> SUCCESS: project_memories folder found.' -ForegroundColor Green; $files = Get-ChildItem $memPath -Filter *.md; if ($files.Count -gt 0) { Write-Host '     Found' $files.Count 'Memory-Files (.md):' -ForegroundColor Gray; foreach ($f in $files) { Write-Host '       -' $f.Name -ForegroundColor Gray } } else { Write-Host '     No .md files inside project_memories.' -ForegroundColor DarkGray } } else { Write-Host '  -> NOTE: No project_memories directory yet. Needs initialization.' -ForegroundColor DarkYellow } }
